sys_relationship.query_with:
(function refineQuery(current, parent) {


    var telcoArray = [];
    var site = parent.getValue('site');
	var priSecCiruit = parent.getValue('pri_sec_circuit');

    if (site) {
        var localCirRec = new GlideAggregate('cmdb_ci_network_circuit');
        localCirRec.addQuery('x_g_sonc_ns_pro_host_ckt', false);
        localCirRec.addQuery('x_g_sonc_ns_pro_site', site);
		localCirRec.addQuery('x_g_sonc_ns_pro_pri_sec_circuit',priSecCiruit);
        localCirRec.groupBy('x_g_sonc_ns_pro_pending_telco_provider');
        localCirRec.query();

        while (localCirRec.next()) {
            telcoArray.push(localCirRec.getValue('x_g_sonc_ns_pro_pending_telco_provider') + '');
        }
        current.addQuery('sys_id', 'IN', telcoArray.join(','));
    }

})(current, parent);
